  const work=options.raw?rawBody:body+'\n'+labels+'\n'+finish;
  const imports='import matplotlib.pyplot as plt\n'+(/\bsns\./.test(body)?'import seaborn as sns\n':'')+'\n';
  Object.assign(r,{dataset:key,question,task:brief+(options.raw?'':` Chart: title "${title}"; x "${options.xlabel||x}"; y "${options.ylabel||y}".`),
   solution:options.target==='value'?body:options.setup?work:imports+(options.raw?'':canvas)+work,setup:options.setup||'',setupDescription:options.setupDescription||'',
   starter:'# Choose the chart operations from the question\n',
   hint:options.hint||decision,demand:decision,decision,fixtureFeature:D[key].feature,prerequisites:['Inspect','Wrangle',...(index?[id]:[])],
   target:options.target||'plot',resultKind:options.target==='value'?'value':'Figure',requiredCalls:[],requiredKeywords:[],forbiddenCalls:[],
   plot:options.target==='value'?null:{textCaseInsensitive:true,...options.rules},contextPlot:{x,y,title,xlabel:options.xlabel||x,ylabel:options.ylabel||y},varietyAuthored:true});
  if(index===0)r.starter=r.solution.replace(options.gap||/sns\.\w+(?=\()/,'____');
  if(index===0&&!r.starter.includes('____'))r.starter=r.solution.replace(options.gap||'fig.tight_layout()','____');
  if(index===0&&!r.starter.includes('____'))r.starter='# Choose the view from the question\n____';
  if(!options.keepTeaching)delete r.teaching;
  r.task='Using df, '+r.task.charAt(0).toLowerCase()+r.task.slice(1);
  changed.push(r.id);return r;
